// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const pa = a.split('.').map(Number);
  const pb = b.split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    if (pa[i] !== pb[i]) return pa[i] < pb[i] ? -1 : 1;
  }
  return 0;
}
