{"content":"// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const pa = parseVersion(a);
  const pb = parseVersion(b);
  for (let i = 0; i < 3; i++) {
    const order = compareNumeric(pa.core[i], pb.core[i]);
    if (order !== 0) return order;
  }

  // A release has higher precedence than any of its pre-releases.
  if (pa.pre.length === 0 || pb.pre.length === 0) {
    if (pa.pre.length === pb.pre.length) return 0;
    return pa.pre.length === 0 ? 1 : -1;
  }

  for (let i = 0; i < Math.min(pa.pre.length, pb.pre.length); i++) {
    const left = pa.pre[i];
    const right = pb.pre[i];
    if (left === right) continue;
    const leftNumeric = /^[0-9]+$/.test(left);
    const rightNumeric = /^[0-9]+$/.test(right);
    if (leftNumeric !== rightNumeric) return leftNumeric ? -1 : 1;
    return leftNumeric ? compareNumeric(left, right) : left < right ? -1 : 1;
  }

  if (pa.pre.length === pb.pre.length) return 0;
  return pa.pre.length < pb.pre.length ? -1 : 1;
}

function parseVersion(version) {
  const withoutBuild = version.split('+', 1)[0];
  const separator = withoutBuild.indexOf('-');
  return {
    core: (separator === -1 ? withoutBuild : withoutBuild.slice(0, separator)).split('.'),
    pre: separator === -1 ? [] : withoutBuild.slice(separator + 1).split('.'),
  };
}

function compareNumeric(a, b) {
  // Valid SemVer numeric identifiers have no leading zeros. Compare strings
  // to avoid rounding identifiers larger than Number.MAX_SAFE_INTEGER.
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a === b ? 0 : a < b ? -1 : 1;
}
