{"new_string":"test('core', () => assert.equal(compareVersions('1.2.3', '1.10.0'), -1));

function assertPrecedes(lower, higher) {
  assert.equal(compareVersions(lower, higher), -1, `${lower} < ${higher}`);
  assert.equal(compareVersions(higher, lower), 1, `${higher} > ${lower}`);
}

test('SemVer 2.0.0 precedence example', () => {
  const versions = [
    '1.0.0-alpha',
    '1.0.0-alpha.1',
    '1.0.0-alpha.beta',
    '1.0.0-beta',
    '1.0.0-beta.2',
    '1.0.0-beta.11',
    '1.0.0-rc.1',
    '1.0.0',
  ];
  for (let i = 0; i < versions.length; i++) {
    assert.equal(compareVersions(versions[i], versions[i]), 0);
    for (let j = i + 1; j < versions.length; j++) {
      assertPrecedes(versions[i], versions[j]);
    }
  }
});

test('core precedence is evaluated before pre-release identifiers', () => {
  assertPrecedes('1.99.99', '2.0.0-alpha');
  assertPrecedes('1.2.99', '1.3.0-alpha');
  assertPrecedes('1.2.3', '1.2.4-alpha');
});

test('numeric identifiers sort numerically and below nonnumeric identifiers', () => {
  assertPrecedes('1.0.0-2', '1.0.0-10');
  assertPrecedes('1.0.0-999', '1.0.0-0a');
  assertPrecedes('1.0.0-1', '1.0.0--');
});

test('nonnumeric identifiers use ASCII order and preserve hyphens', () => {
  assertPrecedes('1.0.0-Z', '1.0.0-a');
  assertPrecedes('1.0.0-alpha-1', '1.0.0-alpha-2');
  assertPrecedes('1.0.0-alpha-10', '1.0.0-alpha-2');
  assertPrecedes('1.0.0-alpha', '1.0.0-alpha-1');
});

test('additional identifiers only decide precedence after an equal prefix', () => {
  assertPrecedes('1.0.0-alpha.1', '1.0.0-alpha.1.0');
  assertPrecedes('1.0.0-alpha.1.9', '1.0.0-alpha.2');
});

test('build metadata does not affect precedence', () => {
  for (const version of ['1.2.3', '1.2.3-alpha.1']) {
    assert.equal(compareVersions(version, `${version}+build.1`), 0);
    assert.equal(compareVersions(`${version}+build.1`, version), 0);
    assert.equal(compareVersions(`${version}+abc`, `${version}+xyz.2-a`), 0);
  }
  assertPrecedes('1.2.3-alpha+zzz', '1.2.3+aaa');
  assertPrecedes('1.2.3+zzz', '1.2.4+aaa');
});

test('large numeric identifiers retain exact precedence', () => {
  assertPrecedes('1.0.0-9007199254740992', '1.0.0-9007199254740993');
  assertPrecedes('9007199254740992.0.0', '9007199254740993.0.0');
  assertPrecedes('1.9007199254740992.0', '1.9007199254740993.0');
  assertPrecedes('1.0.9007199254740992', '1.0.9007199254740993');
});
